"""Exhaustive census: which small groups admit character-equal, mark-different G-sets?

For each group G in a small list, we enumerate all finite G-sets built as disjoint
unions of coset spaces G/H (with bounded multiplicities) and search for pairs with
identical permutation characters but different Burnside mark vectors. Such a pair
refutes the claim that the Molien invariant determines the mark vector up to scaling
(the trivial subgroup always pins the scalar to 1 when the two sets have equal size).

Expected output:
  * cyclic groups Z/n : no such pair exists (characters already separate G-sets);
  * the Klein four group and (Z/3)^2 : pairs exist, and the mark vectors differ
    only at non-cyclic subgroups.

Self-contained; exact integer arithmetic; no external dependencies.
"""

from __future__ import annotations

from fractions import Fraction
from itertools import product
from typing import Callable, Dict, List, Sequence, Tuple

Elem = Tuple[int, ...]


def cyclic(n: int) -> Tuple[List[Elem], Callable[[Elem, Elem], Elem], Elem]:
    return ([(a,) for a in range(n)],
            lambda u, v: ((u[0] + v[0]) % n,),
            (0,))


def elem_abelian(p: int) -> Tuple[List[Elem], Callable[[Elem, Elem], Elem], Elem]:
    return ([(a, b) for a in range(p) for b in range(p)],
            lambda u, v: ((u[0] + v[0]) % p, (u[1] + v[1]) % p),
            (0, 0))


def closure(elements: Sequence[Elem], mul, identity: Elem, gens: Sequence[Elem]) -> Tuple[Elem, ...]:
    seen = {identity}
    stack = [identity]
    while stack:
        x = stack.pop()
        for g in gens:
            y = mul(x, g)
            if y not in seen:
                seen.add(y)
                stack.append(y)
    return tuple(sorted(seen))


def subgroups(elements: Sequence[Elem], mul, identity: Elem) -> List[Tuple[Elem, ...]]:
    found = set()
    for g in elements:
        found.add(closure(elements, mul, identity, [g]))
        for h in elements:
            found.add(closure(elements, mul, identity, [g, h]))
    return sorted(found, key=lambda H: (len(H), H))


def is_cyclic(elements, mul, identity, H: Tuple[Elem, ...]) -> bool:
    return any(len(closure(elements, mul, identity, [h])) == len(H) for h in H)


def coset_space(elements: Sequence[Elem], mul, H: Tuple[Elem, ...]):
    cosets = sorted({tuple(sorted(mul(g, h) for h in H)) for g in elements})
    index = {c: i for i, c in enumerate(cosets)}

    def act(g: Elem, j: int) -> int:
        return index[tuple(sorted(mul(g, y) for y in cosets[j]))]

    return list(range(len(cosets))), act


def gset_from_pieces(elements, mul, pieces: Sequence[Tuple[Elem, ...]]):
    """Disjoint union of the coset spaces G/H for H in `pieces`."""
    blocks = [coset_space(elements, mul, H) for H in pieces]
    points = [(i, j) for i, (pts, _) in enumerate(blocks) for j in pts]

    def act(g: Elem, x):
        i, j = x
        return (i, blocks[i][1](g, j))

    return points, act


def character(elements, points, act) -> Tuple[int, ...]:
    return tuple(sum(1 for x in points if act(g, x) == x) for g in elements)


def mark_vector(subs, points, act) -> Tuple[int, ...]:
    return tuple(sum(1 for x in points if all(act(h, x) == x for h in H)) for H in subs)


def census(name: str, elements, mul, identity, max_size: int, max_mult: int) -> None:
    subs = subgroups(elements, mul, identity)
    cyc_flags = [is_cyclic(elements, mul, identity, H) for H in subs]
    family: List[Tuple[Tuple[int, ...], Tuple[int, ...], Tuple[int, ...]]] = []
    for mult in product(range(max_mult + 1), repeat=len(subs)):
        pieces = [H for H, m in zip(subs, mult) for _ in range(m)]
        size = sum(len(elements) // len(H) for H in pieces)
        if not (0 < size <= max_size):
            continue
        points, act = gset_from_pieces(elements, mul, pieces)
        family.append((mult, character(elements, points, act), mark_vector(subs, points, act)))

    hits: List[Tuple] = []
    for i, (m1, c1, k1) in enumerate(family):
        for (m2, c2, k2) in family[i + 1:]:
            if c1 == c2 and k1 != k2:
                hits.append((m1, m2, c1, k1, k2))

    print(f"{name}: {len(family)} G-sets of size <= {max_size}; "
          f"{len(hits)} character-equal / mark-different pairs")
    if hits:
        m1, m2, c, k1, k2 = hits[0]
        differing = [i for i, (a, b) in enumerate(zip(k1, k2)) if a != b]
        print(f"    common character : {c}")
        print(f"    mark vectors     : {k1}")
        print(f"                       {k2}")
        print(f"    differ at subgroups of orders "
              f"{[len(subs[i]) for i in differing]}; all non-cyclic? "
              f"{all(not cyc_flags[i] for i in differing)}")
        c_scalar = Fraction(k1[0], k2[0])
        print(f"    scalar forced at the trivial subgroup: c = {c_scalar}; "
              f"proportional = {all(a == c_scalar * b for a, b in zip(k1, k2))}")


def main() -> None:
    print("Census of character-equal, mark-different pairs of finite G-sets")
    print("=" * 70)
    for n in (2, 3, 4, 5, 6):
        els, mul, idt = cyclic(n)
        census(f"Z/{n}", els, mul, idt, max_size=8, max_mult=2)
    print()
    for p in (2, 3):
        els, mul, idt = elem_abelian(p)
        census(f"(Z/{p})^2", els, mul, idt, max_size=p * p + p, max_mult=p + 1)
    print()
    print("Conclusion: over cyclic groups the character determines the marks;")
    print("over rank-two elementary abelian groups it does not, and the failure")
    print("is confined to the non-cyclic subgroups.")


if __name__ == "__main__":
    main()

