"""Algorithm: orbit counting by union-find, an averaging-free Molien evaluation."""

from __future__ import annotations

from typing import Callable, Dict, Hashable, List, Sequence

Elem = Hashable
Point = Hashable


class DisjointSet:
    """Union-find with path compression and union by size."""

    def __init__(self, items: Sequence[Point]) -> None:
        self.parent: Dict[Point, Point] = {x: x for x in items}
        self.size: Dict[Point, int] = {x: 1 for x in items}

    def find(self, x: Point) -> Point:
        root = x
        while self.parent[root] != root:
            root = self.parent[root]
        while self.parent[x] != root:
            self.parent[x], x = root, self.parent[x]
        return root

    def union(self, x: Point, y: Point) -> None:
        a, b = self.find(x), self.find(y)
        if a == b:
            return
        if self.size[a] < self.size[b]:
            a, b = b, a
        self.parent[b] = a
        self.size[a] += self.size[b]


def count_orbits(points: Sequence[Point],
                 generators: Sequence[Elem],
                 act: Callable[[Elem, Point], Point]) -> int:
    """Number of orbits of the group generated by `generators` acting on `points`.

    Cost: O(|points| * |generators| * alpha), essentially linear. By Burnside's
    orbit-counting lemma this equals the Molien value
        (1/|H|) * sum_{h in H} |X^h|,
    so the two computations cross-check each other.
    """
    ds = DisjointSet(points)
    for x in points:
        for g in generators:
            ds.union(x, act(g, x))
    return len({ds.find(x) for x in points})


def molien_by_orbits(points: Sequence[Point],
                     generators: Sequence[Elem],
                     act: Callable[[Elem, Point], Point]) -> int:
    """The Molien invariant of the subgroup generated by `generators`."""
    return count_orbits(points, generators, act)


def average_of_cyclic_marks(points: Sequence[Point],
                            subgroup: Sequence[Elem],
                            act: Callable[[Elem, Point], Point],
                            mul: Callable[[Elem, Elem], Elem],
                            identity: Elem) -> float:
    """Average over h in H of mark(<h>) — the Averaging Theorem's right-hand side.

    Equals the Molien invariant of H; this routine makes the theorem checkable.
    """
    total = 0
    for h in subgroup:
        cyc: List[Elem] = [identity]
        cur = h
        while cur != identity:
            cyc.append(cur)
            cur = mul(cur, h)
        total += sum(1 for x in points if all(act(c, x) == x for c in cyc))
    return total / len(subgroup)
